toolArgs.file_text:
/* Chat Layout */
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d31;
    color: #b5bac1;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    color: #fff;
    font-size: 1rem;
    border-bottom: 1px solid #1e1f22;
}

.channel-list {
    list-style: none;
    padding: 8px 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #35373c;
}

.channel-item.active {
    background: #404249;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #949ba4;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #f23f43;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-open {
    flex: 0 0 55%;
}

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #313338;
    min-width: 0;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #313338;
}

.message-area-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.message-area-header .channel-desc {
    font-size: 0.8rem;
    color: #949ba4;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.loading-indicator {
    text-align: center;
    color: #949ba4;
    padding: 8px;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    transition: background 0.1s;
}

.message-bubble.hovered {
    background: #2e3035;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 600;
    color: #f2f3f5;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #949ba4;
}

.message-content {
    color: #dbdee1;
    margin-top: 4px;
    font-size: 0.9rem;
    line-height: 1.4;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dbdee1;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #404249;
    border-color: #5865f2;
}

.thread-link {
    font-size: 0.8rem;
    color: #00a8fc;
    cursor: pointer;
    margin-top: 4px;
    font-weight: 500;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2b2d31;
    border: 1px solid #3f4147;
    border-radius: 4px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.btn-action {
    background: none;
    border: none;
    color: #b5bac1;
    cursor: pointer;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 3px;
}

.btn-action:hover {
    background: #404249;
    color: #fff;
}

.emoji-picker-inline {
    display: flex;
    gap: 2px;
}

.btn-emoji {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 2px 4px;
    border-radius: 3px;
}

.btn-emoji:hover {
    background: #404249;
}

/* Message Input */
.message-input {
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    background: #313338;
}

.message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-input textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.message-input .btn-primary {
    background: #5865f2;
    border: none;
    border-radius: 6px;
    padding: 8px 16px;
    font-weight: 600;
}

.message-input .btn-primary:hover:not(:disabled) {
    background: #4752c4;
}

.message-input .btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
.thread-panel {
    width: 25%;
    min-width: 280px;
    background: #2b2d31;
    border-left: 1px solid #1e1f22;
    display: flex;
    flex-direction: column;
    color: #dbdee1;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
}

.thread-header h6 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
}

.btn-close-thread {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.btn-close-thread:hover {
    background: #404249;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

.thread-root-message p {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #b5bac1;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.thread-reply {
    padding: 6px 0;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}

